//! The catalog of common plasmid parts that feature detection searches for.
//!
//! The data is `data/parts.tsv`, generated by `tools/build-catalog.mjs` and built into the
//! binary with `include_str!`, so detection needs no network and reads no file at run
//! time. Every entry records where its bases came from; `docs/feature-catalog.md` lists
//! the sources and what each one asks for.

use std::sync::OnceLock;

/// The shortest DNA entry worth searching for. Below this, chance matches take over: an
/// 18-mer is expected about once in 3×10^10 bases, a 12-mer once every 17 Mb.
pub const MIN_BASES: usize = 15;

/// The same for a protein entry, which is searched against all six frames. Six residues is
/// about one in 64 million by chance, and it is what the commonest tags need: 6xHis,
/// ENLYFQG and PKKKRKV are all at or below seven.
pub const MIN_RESIDUES: usize = 6;

/// What an entry's `sequence` holds. A tag's DNA depends on the codons whoever ordered it
/// chose, so a peptide is the reliable way to find one; the DNA entries cover the common
/// choices.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Molecule {
    Dna,
    Protein,
}

/// One part to look for. All fields come straight from the catalog file.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Part {
    pub id: &'static str,
    /// What the app shows, and what `src/lib/labinfo.ts` matches on.
    pub name: &'static str,
    /// GenBank feature type, which decides how the part is grouped and coloured.
    pub kind: &'static str,
    pub molecule: Molecule,
    /// Bases, or one-letter residues when `molecule` is `Protein`.
    pub sequence: &'static str,
    /// `ncbi`, `amrfinder` or `literal`.
    pub source: &'static str,
    /// Accession and coordinates it was taken from, or `-` for a published sequence.
    pub accession: &'static str,
    pub licence: &'static str,
    /// PMID or short citation.
    pub reference: &'static str,
    pub note: &'static str,
}

const CATALOG: &str = include_str!("../data/parts.tsv");

/// Every part in the catalog, parsed once.
pub fn parts() -> &'static [Part] {
    static PARTS: OnceLock<Vec<Part>> = OnceLock::new();
    PARTS.get_or_init(|| parse(CATALOG))
}

/// The catalog file as shipped, for tests that check its header and attribution.
pub fn catalog_text() -> &'static str {
    CATALOG
}

/// A short fingerprint of the catalog. Anything that keeps detected results — the
/// construct library's cache — stores this beside them, so results worked out with an
/// older catalog are noticed and done again rather than quietly going stale.
pub fn catalog_version() -> &'static str {
    static VERSION: OnceLock<String> = OnceLock::new();
    VERSION.get_or_init(|| {
        let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
        for b in CATALOG.as_bytes() {
            hash ^= *b as u64;
            hash = hash.wrapping_mul(0x1000_0000_01b3);
        }
        format!("{:016x}", hash)
    })
}

fn parse(text: &'static str) -> Vec<Part> {
    let mut out = Vec::new();
    let mut seen_header = false;
    for line in text.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if !seen_header {
            // The column names, which the generator writes first.
            seen_header = true;
            continue;
        }
        let f: Vec<&str> = line.split('\t').collect();
        if f.len() < 10 {
            continue;
        }
        out.push(Part {
            id: f[0],
            name: f[1],
            kind: f[2],
            molecule: if f[3] == "protein" { Molecule::Protein } else { Molecule::Dna },
            sequence: f[4],
            source: f[5],
            accession: f[6],
            licence: f[7],
            reference: f[8],
            note: f[9],
        });
    }
    out
}
